// existing receipt must never implicitly reserve another100 credits.
export async function testReviewAccess(env,uid,{owner,now=Date.now()}={}){
 identity(env,uid,owner,now);return access(env,uid,owner,now);
}
export async function testReviewCreditSnapshot(db,uid,sessionId){
 const key=rowKey(uid,sessionId),raw=await db.prepare('SELECT v FROM auth_kv WHERE k=?').bind(key).first('v');
 return raw===null?null:{key,raw,row:readReceipt(raw,uid)};
}
